Boolean dei_sc_icon_error( Notify_Pld_Error error_type )
{            
    if( error_type != NOTIFY_PLD_ERROR_RUNTIME_EXPIRED )
    {
        dei_sc_info_set( DEI_SC_INFO_ERROR , error_type );
        
        return dei_sc_tx( DEI_SC_ACK_ERROR_MSG , DEI_SC_PAGGING() || !DEI_SC_LOCK() ? DEI_SC_PAGGING_TX : DEI_SC_NORMAL_TX , 100 ) ; 
    }

    return TRUE ;
}

